public TFMRequestElement parmRequest(TFMRequestElement _request = request)
{
    TFMRequestElement ret;

    ret = super(_request);
    if (_request)
    {
        docRequest = components.getComponent(classStr(MwmsLogicComponentInventoryJournalsCommonHeader)).componentRequest(_request);
    }
    return ret;
}
